import {PARTNERS,findCard,transition} from './model.js';
import {esc,money,date} from './legacy-ui.js';
import {COUNTRIES} from './countries.js';
export const CARD_NOMINALS=[100000,200000,300000,500000,1000000,2000000,2500000,5000000,10000000,20000000,30000000,50000000,100000000,200000000,300000000,500000000];
export const DEFAULT_NOMINALS=[10000000,20000000,30000000,50000000,100000000,500000000];
export const CATEGORIES=[['vehicles','Автомобили и запчасти'],['food','Продукты питания'],['produce','Овощи и фрукты'],['clothing','Одежда, обувь и вещи'],['consumer_goods','Товары народного потребления'],['electronics','Техника и оборудование'],['software','Софт: установка и настройка на месте'],['other_services','Другие услуги']];
export function countryFieldHTML(name,label,value='',{prefix='co-',disabled=false}={}) {
 const id=prefix+name;return `<div class="field"><label for="${id}">${label}</label><select id="${id}" name="${name}" required ${disabled?'disabled':''}><option value="">Выберите страну</option>${COUNTRIES.map(c=>`<option value="${c.code}" ${value===c.code?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div>`;
}
export function selectedCategories(record={},fallback={}) {
 if(Array.isArray(record.categories))return record.categories;
 if(record.category)return [record.category];
 if(Array.isArray(fallback.categories))return fallback.categories;
 return fallback.category?[fallback.category]:[];
}
export function categoryLabels(record={},fallback={}) {return selectedCategories(record,fallback).map(code=>CATEGORIES.find(([key])=>key===code)?.[1]||code).join(', ');}
export function categoryFieldHTML(value=[],{prefix='co-',disabled=false}={}) {
 const selected=Array.isArray(value)?value:value?[value]:[];
 return `<fieldset data-card-categories id="${prefix}category"><legend>Категории товаров и услуг</legend><p class="note">Можно выбрать несколько категорий. Укажите конкретные товары или услуги в описании.</p>${CATEGORIES.map(([code,label])=>`<label class="checkline" for="${prefix}category-${code}"><input id="${prefix}category-${code}" type="checkbox" name="categories" value="${code}" ${selected.includes(code)?'checked':''} ${disabled?'disabled':''}><span>${label}</span></label>`).join('')}<small class="note">Категория «Софт» — установка и настройка ПО на месте вне РФ. Цифровые лицензии, подписки и онлайн-доступ требуют отдельных условий.</small></fieldset>`;
}
export function nominalFieldsHTML(company={},program={},disabled=false) {
 const selected=Array.isArray(company.nominals)&&company.nominals.length?company.nominals:Array.isArray(program.nominals)&&program.nominals.length?program.nominals:DEFAULT_NOMINALS;
 return `<fieldset data-card-nominals><legend>Допустимые номиналы карт</legend><p class="note">Отметьте хотя бы один номинал от 1 000 до 5 000 000 ₽. Рекомендуемые номиналы уже выбраны; список можно изменить до подписания договора.</p>${CARD_NOMINALS.map(n=>`<label class="checkline"><input name="nominals" type="checkbox" value="${n}" ${selected.includes(n)?'checked':''} ${disabled?'disabled':''}><span>${money(n/100)}</span></label>`).join('')}</fieldset>`;
}
export const COMPANY_FIELDS=[
 ['name','Полное наименование компании','text'],['reg','Регистрационный номер','text'],['tax','Налоговый номер','text'],['address','Юридический адрес','text'],['role','Должность подписанта','text'],['director','ФИО подписанта','text'],['authority','Основание полномочий','text'],['email','Email для договора и уведомлений','email'],['phone','Телефон','tel'],['bank','Банк получателя','text'],['account','Расчётный счёт / IBAN','text'],['swift','SWIFT / банковский код','text'],['goods','Товары или услуги программы','text'],['rules','Ссылка на правила карт и основной договор','url'],['issueTime','Срок выпуска кода по запросу','text'],['requestTime','Срок запроса выпуска после оплаты','text'],['validity','Срок действия выпущенной карты','text'],['redemption','Порядок погашения и частичное использование','text'],['exchangeChannel','Канал обмена реестрами и подтверждениями','text']
];
// Recommendations populate only missing fields. Saving still requires the supplier's confirmation.
export const COMPANY_RECOMMENDATIONS=Object.freeze({
 rules:{value:'https://pina.market/#/legal/terms',hint:'Оферта Pina Market по картам. Можно указать другую HTTPS-ссылку на условия программы. Договор на сам товар или услугу заключается с поставщиком отдельно.'},
 issueTime:{value:'Не позднее одного рабочего дня после запроса покупателя',hint:'Рекомендуем один рабочий день. Это максимальное время ожидания кода после нажатия «Получить сертификат».'},
 requestTime:{value:'В течение 365 дней после подтверждения оплаты',hint:'Рекомендуем 365 дней. В течение этого времени покупатель может запросить ещё не выпущенный код.'},
 validity:{value:'180 дней со дня выпуска кода',hint:'Рекомендуем 180 дней. Столько времени есть на предъявление выпущенного кода поставщику. Укажите число дней, например «90 дней».'},
 redemption:{value:'Карта погашается однократно на полный номинал в счёт договора или заказа покупателя у эмитента. Частичное погашение не предусмотрено.',hint:'Текущая программа поддерживает однократное полное погашение. Частичное использование требует отдельной настройки сервиса.'},
 exchangeChannel:{value:'Личный кабинет поставщика на Pina Market',hint:'Здесь поставщик получает реестры, передаёт документы и подтверждает расчёты.'}
});
const PROGRAM_COMPANY_KEYS={rules:'rules',issueTime:'issue_deadline',requestTime:'request_deadline',validity:'validity',redemption:'redemption'};
const filled=value=>value!==null&&value!==undefined&&String(value).trim()!=='';
export function companyFieldValue(company,key,program={}) {
 if(filled(company[key]))return company[key];
 if(filled(program[PROGRAM_COMPANY_KEYS[key]]))return program[PROGRAM_COMPANY_KEYS[key]];
 if(key==='validity'&&Number(program.expires_seconds)>0)return `${Number(program.expires_seconds)/86400} дней со дня выпуска кода`;
 return COMPANY_RECOMMENDATIONS[key]?.value||'';
}
export function companyFieldsHTML(company,{prefix='co-',disabled=false,program={}}={}) {
 const legacyCountry=['KG','Кыргызстан','Кыргызская Республика'].includes(program.use_country)?'KG':'';
 return countryFieldHTML('country','Страна регистрации компании',company.country||legacyCountry,{prefix,disabled})+categoryFieldHTML(selectedCategories(company,program),{prefix,disabled})+COMPANY_FIELDS.map(([key,label,type])=>{
  const id=prefix+key,recommendation=COMPANY_RECOMMENDATIONS[key],value=esc(String(companyFieldValue(company,key,program)));
  const attrs=`id="${id}" name="${key}" required maxlength="500" ${disabled?'disabled':''} ${recommendation?`aria-describedby="${id}-hint"`:''}`;
  const control=key==='redemption'?`<textarea ${attrs} rows="3">${value}</textarea>`:`<input ${attrs} type="${type}" value="${value}">`;
  return `<div class="field"><label for="${id}">${key==='rules'?'Ссылка на оферту по картам':label}</label>${control}${recommendation?`<small class="note" id="${id}-hint">${esc(recommendation.hint)}</small>`:''}</div>`;
 }).join('')+countryFieldHTML('fulfillmentCountry','Страна фактической передачи товара или оказания услуги',company.fulfillmentCountry||program.country_code||legacyCountry||company.country||'',{prefix,disabled})+nominalFieldsHTML(company,program,disabled);
}
export function programFormValues(company,program={}) {
 const validity=companyFieldValue(company,'validity',program);
 const match=String(validity).trim().match(/^(\d+)\s*(?:день|дня|дней|дн\.?)(?:\s+со\s+дня\s+выпуска(?:\s+кода)?)?\.?$/iu);
 const days=filled(company.validity)?(match?Number(match[1]):''):(program.days??(Number(program.expires_seconds)>0?Number(program.expires_seconds)/86400:match?Number(match[1]):''));
 return {...program,days,categories:selectedCategories(company,program),category:company.category||program.category||'',country_code:company.fulfillmentCountry||program.country_code||(['KG','Кыргызстан','Кыргызская Республика'].includes(program.use_country)?'KG':company.country||''),rules:companyFieldValue(company,'rules',program),issue_deadline:companyFieldValue(company,'issueTime',program),request_deadline:companyFieldValue(company,'requestTime',program),redemption:companyFieldValue(company,'redemption',program)};
}
export function ensureMerchant(s) {s.merchant??={partner:'auto',company:{},contract:null,uploaded:null,acks:[]};return s.merchant;}
export function merchantCards(s) {const m=ensureMerchant(s);return s.orders.filter(o=>o.partner===m.partner).flatMap(order=>order.cards.filter(c=>c.redemption==='redeemed').map(card=>({order,card})));}
export function merchantTotals(s) {const rows=merchantCards(s),confirmed=rows.filter(x=>x.card.settlementConfirmed);return {redeemed:rows.reduce((a,x)=>a+x.card.nominal,0),balance:rows.reduce((a,x)=>a+x.card.nominal,0),released:confirmed.reduce((a,x)=>a+x.card.nominal,0),unpaid:rows.filter(x=>x.card.settlement!=='credited'&&x.order.settlement!=='credited').reduce((a,x)=>a+x.card.nominal,0),awaiting:rows.filter(x=>!x.card.settlementConfirmed&&(x.card.settlement==='credited'||x.order.settlement==='credited'))};}
export function acceptMerchantCode(s,{code,buyer,contract}) {
 const merchant=ensureMerchant(s);code=String(code||'').trim();
 const match=s.orders.filter(o=>o.partner===merchant.partner).flatMap(order=>order.cards.map(card=>({order,card}))).find(({card})=>card.code===code);
 if(!match)throw Error('Код не найден для вашей компании. Проверьте код и выбранного демо-поставщика.');
 transition(s,'redeem',match.card.id,{buyer,contract});return match;
}
export function acknowledgeSettlement(s,{ids,bankref,amount}) {
 const m=ensureMerchant(s);if(!ids.length)throw Error('Нет карт с подтверждённым переводом.');
 if(!bankref?.trim()||!Number.isFinite(Number(amount))||Number(amount)<=0)throw Error('Укажите банковское подтверждение и фактически полученную сумму.');
 const rows=ids.map(id=>findCard(s,id));
 if(rows.some(({order:o,card:c})=>o.partner!==m.partner||c.redemption!=='redeemed'||c.settlementConfirmed||c.refund!=='none'||(c.settlement!=='credited'&&o.settlement!=='credited')))throw Error('Реестр изменился или операция не готова к подтверждению.');
 const nominal=rows.reduce((a,x)=>a+x.card.nominal,0),expected=nominal*991/1000;
 if(Math.round(Number(amount)*100)!==Math.round(expected*100))throw Error('Сумма не совпадает с демо-реестром после удержаний. Проверьте перевод; при расхождении обратитесь в поддержку.');
 const ack={id:'ACK-'+crypto.randomUUID(),cards:[...ids],nominal,received:Number(amount),bankref:bankref.trim(),date:new Date().toISOString(),balanceReview:'manual_review'};
 rows.forEach(({card:c})=>{c.settlementConfirmed=true;c.ackId=ack.id;});m.acks.unshift(ack);return ack;
}
export function merchantContent(s,tab,{icon,btn}) {
 const m=ensureMerchant(s),p=PARTNERS.find(p=>p.id===m.partner),t=merchantTotals(s);
 const intro=`<div class="merchant-context"><span>${icon('merchant')}Демо-роль поставщика</span><label for="merchant-context">Программа</label><select id="merchant-context">${PARTNERS.map(p=>`<option value="${p.id}" ${m.partner===p.id?'selected':''}>${p.issuer}</option>`).join('')}</select><small>В рабочем сервисе компания определяется учётной записью.</small></div>`;
 if(tab==='company') return `${intro}<div class="merchant-company-layout"><div><section class="panel"><p class="eyebrow">Рамочный договор</p><h2>Один договор.<br>Все ваши карты.</h2><p>Заполните реквизиты и условия программы. Получите документ с реквизитами Pina Market и вашей компании.</p><ol class="onboarding-steps"><li>Заполните сведения</li><li>Скачайте договор</li><li>Подпишите и загрузите экземпляр</li><li>Дождитесь проверки подключения</li></ol><a href="/giftcards/r-51b300a837e2fe34/assets/agency-template.docx" download class="text-link">Скачать незаполненный шаблон ${icon('contract')}</a><div class="notice">Файл подписи Pina Market ещё не добавлен. Сейчас формируется проект с демонстрационным номером, а не подписанный договор.</div></section><section class="panel contract-status"><h3>Мои документы</h3>${m.contract?`<p><b>${esc(m.contract.number)}</b><br>Создан ${date(m.contract.date)}</p><span class="badge review">Ожидает подписи Pina Market</span>${btn('Скачать заполненный проект','contract-download','outline full')}`:'<p>Сначала заполните форму справа.</p>'}<hr><h3>Подписанный экземпляр</h3><p class="note">Для демонстрации выбирайте только тестовый PDF или DOCX до 10 МБ. Файл остаётся локально в браузере и не считается проверенным договором.</p><label class="upload-control" for="signed-contract">${icon('contract')}Выбрать файл<input id="signed-contract" type="file" accept=".pdf,.docx,application/pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document"></label>${m.uploaded?`<div class="notice"><b>${esc(m.uploaded.name)}</b><br>Сохранён в этом браузере. Статус: ожидает проверки. ${btn('Скачать загруженный файл','contract-upload-download','textbtn')}</div>`:''}</section></div><form id="company-form" novalidate class="panel form-panel"><p class="eyebrow">Реквизиты эмитента</p><h2>Данные вашей компании</h2><p class="note">Укажите страну регистрации и место исполнения вне РФ. Используйте тестовые сведения в прототипе.</p><div class="fields"><p class="notice">Типовые условия карт уже заполнены. Проверьте их и при необходимости измените перед сохранением.</p>${companyFieldsHTML(m.company)}<div class="notice"><b>Коммерческие условия шаблона</b><br>Вознаграждение Pina Market — 0,1% номинала принятых карт. Комиссии финансовой организации: 0,2% валютный контроль и 0,6% перевод. Удержания не уменьшают номинал покупателя. Изменения согласовываются отдельно.</div><label class="checkline"><input type="checkbox" required name="agree"><span>Проверил сведения и условия. Понимаю, что в прототипе формируется проект без действующей подписи.</span></label><p class="form-error" role="alert" hidden></p><button class="btn full">Сохранить и подготовить договор ${icon('arrow')}</button></div></form></div>`;
 if(tab==='registry') return `${intro}<div class="subhead"><h2>Реестр принятых карт</h2>${btn('Скачать CSV','registry-csv','outline small')}</div>${registry(s,icon)}<div class="notice">В реестр входят идентификатор карты, сумма, покупатель, договор и дата приёма. Полные секретные коды в выгрузку не попадают.</div>`;
 if(tab==='settlements') return `${intro}<div class="merchant-stat-grid"><article class="summary-stat"><span>Учётный остаток по картам</span><strong>${money(t.balance)}</strong><p>Номинал принятых карт в демонстрации</p></article><article class="summary-stat"><span>Ожидается банковский перевод</span><strong>${money(t.unpaid*991/1000)}</strong><p>Демо-расчёт после удержаний 0,9%</p></article><article class="summary-stat"><span>Банковские расчёты подтверждены</span><strong>${money(t.released)}</strong><p>Номинал по подтверждённым поступлениям</p></article></div><section class="panel settlement-confirm"><h2>Получили перевод от Pina Market?</h2><p>Сверьте банковское поступление с реестром. После вашего подтверждения оператор отдельно сверит учётный остаток платформы. Автоматический перевод остатка не выполняется.</p><p class="note">Учётный остаток не является банковским счётом. Денежный перевод и движение учётного остатка — разные события.</p>${t.awaiting.length?`<div class="notice">К подтверждению: ${t.awaiting.length} карт, номинал ${money(t.awaiting.reduce((a,x)=>a+x.card.nominal,0))}. Сумма перевода после удержаний: <b>${money(t.awaiting.reduce((a,x)=>a+x.card.nominal,0)*991/1000)}</b>.</div>${btn('Подтвердить получение перевода','ack-settlement')}`:'<div class="empty">Пока нет банковских переводов, ожидающих вашего подтверждения.</div>'}</section><section class="panel"><h3>Подтверждения расчётов</h3>${m.acks.length?m.acks.map(a=>`<div class="ack-row"><b>${money(a.received)}</b><span>${date(a.date)} · ${esc(a.bankref)}</span><small>Номинал ${money(a.nominal)} · ${a.cards.length} карт · ${a.balanceReview==='reconciled'?'Остаток сверен вручную':'Ожидает ручной сверки остатка'}</small></div>`).join(''):'<p class="note">История появится после подтверждения первого перевода.</p>'}</section>`;
 return `${intro}<div class="merchant-dashboard"><section class="panel redeem-panel"><p class="eyebrow">Приём карты</p><h2>Клиент передал код?<br>Примите его по заказу.</h2><p>Проверьте код карты вашей компании и укажите, в счёт какого договора или заказа вы принимаете номинал.</p><form id="merchant-redeem-form" class="fields"><div class="field"><label for="merchant-code">Код сертификата</label><input id="merchant-code" name="code" required maxlength="100" autocomplete="off" placeholder="Введите демонстрационный код"></div><div class="form-grid"><div class="field"><label for="merchant-buyer">ФИО покупателя</label><input id="merchant-buyer" name="buyer" required maxlength="150" autocomplete="off"></div><div class="field"><label for="merchant-contract">Договор или заказ</label><input id="merchant-contract" name="contract" required maxlength="100" placeholder="Номер или идентификатор"></div></div><p class="form-error" role="alert" hidden></p><button class="btn full">Проверить и принять карту ${icon('redemption')}</button></form><p class="note">Демо: создайте карту в кабинете покупателя и используйте её код здесь. Код другой компании не будет принят.</p></section><div><article class="overview-main merchant-balance"><p>Учётный остаток · RUB</p><h2>${money(t.balance)}</h2><span>Номинал принятых карт до подтверждения расчёта</span><a href="#/merchant/settlements" class="btn lime small">Расчёты ${icon('arrow')}</a><div class="overview-decoration">${icon('reports')}</div></article><section class="panel merchant-onboarding"><h3>Документы компании</h3><p>Реквизиты, заполненный договор и загрузка подписанного экземпляра — в одном разделе.</p><a class="text-link" href="#/merchant/company">Реквизиты и договор ${icon('arrow')}</a></section></div></div><div class="subhead"><h2>Последние приёмы</h2><a class="text-link" href="#/merchant/registry">Весь реестр ${icon('arrow')}</a></div>${registry(s,icon,5)}`;
}
function registry(s,icon,limit=1000) {const rows=merchantCards(s).slice(0,limit);return `<div class="panel merchant-registry"><div class="table-wrap"><table><thead><tr><th>Карта / дата</th><th>Покупатель</th><th>Договор / заказ</th><th>Номинал</th><th>Расчёт</th></tr></thead><tbody>${rows.map(({order:o,card:c})=>`<tr><td><b>${esc(c.id)}</b><small>${date(c.redeemedAt)}</small></td><td>${esc(c.buyer)}</td><td>${esc(c.contract)}</td><td>${money(c.nominal)}</td><td><span class="badge ${c.settlementConfirmed?'ready':'review'}">${c.settlementConfirmed?'Подтверждён':'Ожидает расчёта'}</span>${c.refund==='requested'?'<small>Обращение на возврат</small>':''}</td></tr>`).join('')||'<tr><td colspan="5">Пока нет принятых карт.</td></tr>'}</tbody></table></div></div>`;}
export function registryCSV(s) {const field=v=>'"'+String(v??'').replace(/^[=+@\-\t\r]/,'\'$&').replace(/"/g,'""')+'"';return '\ufeff'+[['Карта','Заказ Pina','Дата','ФИО покупателя','Договор / заказ','Номинал RUB','Расчёт'],...merchantCards(s).map(({order:o,card:c})=>[c.id,o.id,c.redeemedAt,c.buyer,c.contract,c.nominal,c.settlementConfirmed?'Подтверждён':'Ожидает'])].map(r=>r.map(field).join(';')).join('\r\n');}
